// Embed the exact #509 helper sources; standalone clients need only Docker.
import { readFileSync, writeFileSync } from 'node:fs';
const paths = ['container/storage/Dockerfile', 'src/caller-storage-manager.ts',
  'src/caller-storage-manager-cli.ts', 'src/caller-runtime-sqlite.ts'];
const files = Object.fromEntries(paths.map(path => [`packages/client/${path}`,
  readFileSync(new URL(`../${path}`, import.meta.url), 'utf8')]));
writeFileSync(new URL('../src/caller-storage-assets.ts', import.meta.url),
  '// Generated by scripts/generate-storage-image.mjs; do not edit by hand.\n' +
  'export const STORAGE_IMAGE_FILES: Readonly<Record<string, string>> = ' + JSON.stringify(files, null, 2) + ';\n');
